// Minimal re-implementation of the subset of Python's argparse behavior needed
// for this program: three required string options (--key1, --key2, --data),
// plus the automatic -h/--help option. Mirrors argparse's output format and
// exit codes (0 for --help, 2 for usage errors).

const OPTIONS = [
  { name: '--key1', dest: 'key1', metavar: 'KEY1' },
  { name: '--key2', dest: 'key2', metavar: 'KEY2' },
  { name: '--data', dest: 'data', metavar: 'DATA' },
];

function usageLine(prog) {
  return `usage: ${prog} [-h] --key1 KEY1 --key2 KEY2 --data DATA`;
}

function printUsageError(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog) {
  const lines = [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help   show this help message and exit',
  ];
  for (const opt of OPTIONS) {
    lines.push(`  ${opt.name} ${opt.metavar}`);
  }
  process.stdout.write(lines.join('\n') + '\n');
  process.exit(0);
}

export function parseArgs(argv, prog) {
  const result = {};
  const unrecognized = [];

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];

    if (arg === '-h' || arg === '--help') {
      printHelp(prog);
    }

    // Split "--opt=value" into option string and inline value.
    let optName = arg;
    let inlineValue = null;
    if (arg.startsWith('--')) {
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        optName = arg.slice(0, eq);
        inlineValue = arg.slice(eq + 1);
      }
    }

    const opt = OPTIONS.find((o) => o.name === optName);
    if (opt === undefined) {
      unrecognized.push(arg);
      i += 1;
      continue;
    }

    if (inlineValue !== null) {
      result[opt.dest] = inlineValue;
      i += 1;
    } else {
      if (i + 1 >= argv.length) {
        printUsageError(prog, `argument ${opt.name}: expected one argument`);
      }
      result[opt.dest] = argv[i + 1];
      i += 2;
    }
  }

  // argparse checks required arguments before reporting unrecognized ones.
  const missing = OPTIONS.filter((o) => !(o.dest in result)).map((o) => o.name);
  if (missing.length > 0) {
    printUsageError(
      prog,
      `the following arguments are required: ${missing.join(', ')}`,
    );
  }

  if (unrecognized.length > 0) {
    printUsageError(prog, `unrecognized arguments: ${unrecognized.join(' ')}`);
  }

  return { key1: result.key1, key2: result.key2, data: result.data };
}

