// test15.mjs — Node.js (ESM) port of test15.py.
//
// Mirrors the Python original exactly:
//   1. Parse --key1, --key2, --data (all required strings).
//   2. Encrypt the UTF-8 encoded data with key1 under AES-ECB.
//   3. Decrypt the resulting ciphertext with key2 (the "wrong" key).
//   4. Print the Python bytes-repr of both the ciphertext and the
//      wrong plaintext.
//
// Any error (bad arguments, invalid key size, data not a multiple of
// the block size) propagates uncaught so the process exits non-zero,
// matching the Python behavior of exiting 1 with a traceback on stderr.

import { basename } from 'node:path';
import { fileURLToPath } from 'node:url';

import { AESModeOfOperationECB } from './ecb_mode.mjs';
import { pyBytesRepr } from './pybytes.mjs';
import { parseArgs } from './argparse.mjs';

// Python's str.encode() defaults to UTF-8. The inputs are ASCII in
// practice, but encode as UTF-8 to match Python semantics exactly.
function encodeUtf8(s) {
  return new TextEncoder().encode(s);
}

function main() {
  // Python argparse derives the program name from basename(sys.argv[0]);
  // here that is the basename of this script file.
  const prog = basename(fileURLToPath(import.meta.url));

  const args = parseArgs(prog, process.argv.slice(2), {
    key1: { type: 'str', required: true }, // First 16 bytes key
    key2: { type: 'str', required: true }, // Second 16 bytes key
    data: { type: 'str', required: true }, // 16 bytes data
  });

  // Encrypt with first key, decrypt with second key
  const aes1 = new AESModeOfOperationECB(encodeUtf8(args.key1)); // Initialize first AES ECB cipher
  const aes2 = new AESModeOfOperationECB(encodeUtf8(args.key2)); // Initialize second AES ECB cipher
  const ciphertext = aes1.encrypt(encodeUtf8(args.data)); // Encrypt with first key
  const wrongPlaintext = aes2.decrypt(ciphertext); // Try to decrypt with wrong key
  console.log(pyBytesRepr(ciphertext));
  console.log(pyBytesRepr(wrongPlaintext));
}

main();

