import { spawnSync } from 'node:child_process';

const CHILD = '/tmp/argparse_child.mjs';
const USAGE = 'usage: prog.mjs [-h] --key1 KEY1 --key2 KEY2 --data DATA';

let failures = 0;
function check(label, actual, expected) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (!ok) {
    failures += 1;
    console.log(`FAIL: ${label}`);
    console.log(`  expected: ${JSON.stringify(expected)}`);
    console.log(`  actual:   ${JSON.stringify(actual)}`);
  } else {
    console.log(`PASS: ${label}`);
  }
}

function run(args) {
  const r = spawnSync(process.execPath, [CHILD, ...args], { encoding: 'utf8' });
  return { code: r.status, stdout: r.stdout, stderr: r.stderr };
}

// 1. Success, space-separated form
{
  const r = run(['--key1', 'k1', '--key2', 'k2', '--data', 'dd']);
  check('success: exit code', r.code, 0);
  check('success: stdout', r.stdout, JSON.stringify({ key1: 'k1', key2: 'k2', data: 'dd' }) + '\n');
  check('success: stderr', r.stderr, '');
}

// 2. Success, =form (mixed, different order)
{
  const r = run(['--data=d d', '--key1=k 1', '--key2', 'k2']);
  check('=form: exit code', r.code, 0);
  check('=form: stdout', r.stdout, JSON.stringify({ key1: 'k 1', key2: 'k2', data: 'd d' }) + '\n');
}

// 3. Missing args (all)
{
  const r = run([]);
  check('missing-all: exit code', r.code, 2);
  check('missing-all: stderr', r.stderr,
    USAGE + '\n' + 'prog.mjs: error: the following arguments are required: --key1, --key2, --data\n');
}

// 4. Missing args (subset, declaration order)
{
  const r = run(['--data', 'x']);
  check('missing-subset: exit code', r.code, 2);
  check('missing-subset: stderr', r.stderr,
    USAGE + '\n' + 'prog.mjs: error: the following arguments are required: --key1, --key2\n');
}

// 5. Unrecognized argument
{
  const r = run(['--key1', 'k1', '--key2', 'k2', '--data', 'dd', '--bogus', 'zzz']);
  check('unknown: exit code', r.code, 2);
  check('unknown: stderr', r.stderr,
    USAGE + '\n' + 'prog.mjs: error: unrecognized arguments: --bogus zzz\n');
}

// 6. -h
{
  const expectedHelp = [
    USAGE,
    '',
    'options:',
    '  -h, --help   show this help message and exit',
    '  --key1 KEY1',
    '  --key2 KEY2',
    '  --data DATA',
  ].join('\n') + '\n';
  const r = run(['-h']);
  check('-h: exit code', r.code, 0);
  check('-h: stdout', r.stdout, expectedHelp);
  check('-h: stderr', r.stderr, '');

  const r2 = run(['--help']);
  check('--help: exit code', r2.code, 0);
  check('--help: stdout', r2.stdout, expectedHelp);
}

// 7. Missing value for an option
{
  const r = run(['--key1', 'k1', '--key2', 'k2', '--data']);
  check('no-value: exit code', r.code, 2);
  check('no-value: stderr', r.stderr,
    USAGE + '\n' + 'prog.mjs: error: argument --data: expected one argument\n');
}

// 8. Real-world style values (from the reference invocation)
{
  const r = run(['--key1', 'QU$h{ecq^#qb{L3M', '--key2', '%%3u+dl)X>Iur%O(', '--data', '^Z-jz9z*elH|LaA0']);
  check('reference values: stdout', r.stdout,
    JSON.stringify({ key1: 'QU$h{ecq^#qb{L3M', key2: '%%3u+dl)X>Iur%O(', data: '^Z-jz9z*elH|LaA0' }) + '\n');
}

process.exit(failures === 0 ? 0 : 1);

