// Pure-JavaScript AES block cipher (FIPS-197), supporting AES-128/192/256.
// Single-block encryption/decryption; mode handling lives elsewhere.

import { SBOX, INV_SBOX, RCON } from './aes_tables.mjs';

// Multiply by x (i.e. 0x02) in GF(2^8) with the AES reduction polynomial.
function xtime(a) {
  a <<= 1;
  if (a & 0x100) a ^= 0x11b;
  return a & 0xff;
}

// Multiply two bytes in GF(2^8).
function gmul(a, b) {
  let p = 0;
  while (b > 0) {
    if (b & 1) p ^= a;
    a = xtime(a);
    b >>= 1;
  }
  return p;
}

// Expand `key` (16/24/32 bytes) into Nr+1 round keys of 16 bytes each.
// Returns a Uint8Array of 16 * (Nr + 1) bytes.
function expandKey(key) {
  const Nk = key.length / 4; // words in the cipher key: 4, 6, or 8
  const Nr = Nk + 6; // number of rounds: 10, 12, or 14
  const w = new Uint8Array(16 * (Nr + 1));
  w.set(key);

  for (let i = Nk; i < 4 * (Nr + 1); i++) {
    const o = 4 * i;
    let t0 = w[o - 4];
    let t1 = w[o - 3];
    let t2 = w[o - 2];
    let t3 = w[o - 1];
    if (i % Nk === 0) {
      // RotWord + SubWord + Rcon
      const r = RCON[i / Nk];
      const n0 = SBOX[t1] ^ r;
      const n1 = SBOX[t2];
      const n2 = SBOX[t3];
      const n3 = SBOX[t0];
      t0 = n0; t1 = n1; t2 = n2; t3 = n3;
    } else if (Nk > 6 && i % Nk === 4) {
      // SubWord only (AES-256)
      t0 = SBOX[t0];
      t1 = SBOX[t1];
      t2 = SBOX[t2];
      t3 = SBOX[t3];
    }
    const p = o - 4 * Nk;
    w[o] = w[p] ^ t0;
    w[o + 1] = w[p + 1] ^ t1;
    w[o + 2] = w[p + 2] ^ t2;
    w[o + 3] = w[p + 3] ^ t3;
  }
  return w;
}

function addRoundKey(state, w, round) {
  const o = 16 * round;
  for (let i = 0; i < 16; i++) state[i] ^= w[o + i];
}

function subBytes(state) {
  for (let i = 0; i < 16; i++) state[i] = SBOX[state[i]];
}

function invSubBytes(state) {
  for (let i = 0; i < 16; i++) state[i] = INV_SBOX[state[i]];
}

// State is column-major: byte (row r, col c) lives at index r + 4 * c.
function shiftRows(state) {
  for (let r = 1; r < 4; r++) {
    const row = [state[r], state[r + 4], state[r + 8], state[r + 12]];
    for (let c = 0; c < 4; c++) state[r + 4 * c] = row[(c + r) % 4];
  }
}

function invShiftRows(state) {
  for (let r = 1; r < 4; r++) {
    const row = [state[r], state[r + 4], state[r + 8], state[r + 12]];
    for (let c = 0; c < 4; c++) state[r + 4 * c] = row[(c - r + 4) % 4];
  }
}

function mixColumns(state) {
  for (let c = 0; c < 4; c++) {
    const o = 4 * c;
    const s0 = state[o];
    const s1 = state[o + 1];
    const s2 = state[o + 2];
    const s3 = state[o + 3];
    state[o] = xtime(s0) ^ (xtime(s1) ^ s1) ^ s2 ^ s3;
    state[o + 1] = s0 ^ xtime(s1) ^ (xtime(s2) ^ s2) ^ s3;
    state[o + 2] = s0 ^ s1 ^ xtime(s2) ^ (xtime(s3) ^ s3);
    state[o + 3] = (xtime(s0) ^ s0) ^ s1 ^ s2 ^ xtime(s3);
  }
}

function invMixColumns(state) {
  for (let c = 0; c < 4; c++) {
    const o = 4 * c;
    const s0 = state[o];
    const s1 = state[o + 1];
    const s2 = state[o + 2];
    const s3 = state[o + 3];
    state[o] = gmul(s0, 0x0e) ^ gmul(s1, 0x0b) ^ gmul(s2, 0x0d) ^ gmul(s3, 0x09);
    state[o + 1] = gmul(s0, 0x09) ^ gmul(s1, 0x0e) ^ gmul(s2, 0x0b) ^ gmul(s3, 0x0d);
    state[o + 2] = gmul(s0, 0x0d) ^ gmul(s1, 0x09) ^ gmul(s2, 0x0e) ^ gmul(s3, 0x0b);
    state[o + 3] = gmul(s0, 0x0b) ^ gmul(s1, 0x0d) ^ gmul(s2, 0x09) ^ gmul(s3, 0x0e);
  }
}

function checkArgs(key, block) {
  if (!(key instanceof Uint8Array) || (key.length !== 16 && key.length !== 24 && key.length !== 32)) {
    throw new Error('Invalid key size');
  }
  if (!(block instanceof Uint8Array) || block.length !== 16) {
    throw new Error('Invalid block size');
  }
}

// Encrypt one 16-byte block. `key` must be 16, 24, or 32 bytes.
// Returns a new Uint8Array(16).
export function aesEncryptBlock(key, block) {
  checkArgs(key, block);
  const w = expandKey(key);
  const Nr = w.length / 16 - 1;
  const state = new Uint8Array(block);

  addRoundKey(state, w, 0);
  for (let round = 1; round < Nr; round++) {
    subBytes(state);
    shiftRows(state);
    mixColumns(state);
    addRoundKey(state, w, round);
  }
  subBytes(state);
  shiftRows(state);
  addRoundKey(state, w, Nr);
  return state;
}

// Decrypt one 16-byte block. `key` must be 16, 24, or 32 bytes.
// Returns a new Uint8Array(16).
export function aesDecryptBlock(key, block) {
  checkArgs(key, block);
  const w = expandKey(key);
  const Nr = w.length / 16 - 1;
  const state = new Uint8Array(block);

  addRoundKey(state, w, Nr);
  for (let round = Nr - 1; round >= 1; round--) {
    invShiftRows(state);
    invSubBytes(state);
    addRoundKey(state, w, round);
    invMixColumns(state);
  }
  invShiftRows(state);
  invSubBytes(state);
  addRoundKey(state, w, 0);
  return state;
}

