// Decrypt one 16-byte block. `key` must be 16, 24, or 32 bytes.
// Returns a new Uint8Array(16).
export function aesDecryptBlock(key, block) {
  checkArgs(key, block);
  const w = expandKey(key);
  const Nr = w.length / 16 - 1;
  const state = new Uint8Array(block);

  addRoundKey(state, w, Nr);
  for (let round = Nr - 1; round >= 1; round--) {
    invShiftRows(state);
    invSubBytes(state);
    addRoundKey(state, w, round);
    invMixColumns(state);
  }
  invShiftRows(state);
  invSubBytes(state);
  addRoundKey(state, w, 0);
  return state;
}

