  for (let i = 0; i < out.length; i++) out[i] = parseInt(s.slice(2 * i, 2 * i + 2), 16);
  return out;
}

let failures = 0;
function check(name, actual, expected) {
  const ok = hex(actual) === expected;
  if (!ok) failures++;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}: got ${hex(actual)}${ok ? '' : `, want ${expected}`}`);
}

const pt = fromHex('00112233445566778899aabbccddeeff');

// FIPS-197 Appendix B / C.1 AES-128
const k128 = fromHex('000102030405060708090a0b0c0d0e0f');
const c128 = aesEncryptBlock(k128, pt);
